select exists (select 1 from information_schema.columns where table_schema='public' and table_name='quiz_questions' and column_name='question_image_url') and exists (select 1 from information_schema.columns where table_schema='public' and table_name='quiz_questions' and column_name='option_image_urls') and exists (select 1 from storage.buckets where id='quiz-images' and public) as ok, exists (select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='quiz_images_public_select') as storage_ok;
